/* Jira Datacenter Dark Theme - Cloud Style (только для Jira) */

/* i really want this to be global */
/* Jira Datacenter Dark Theme - Cloud Style (без CSS переменных) */

/* Основной фон */
body, #page, .jira-page-container {
    background-color: #1D2125 !important;
    color: #B6C2CF !important;
}

/* Хедер */
#header, .aui-header {
    background-color: #22272B !important;
    border-bottom: 1px solid #454F59 !important;
}

#header .aui-nav > li > a,
.aui-header .aui-nav > li > a {
    color: #B6C2CF !important;
}

#header .aui-nav > li > a:hover,
.aui-header .aui-nav > li > a:hover {
    background-color: #313840 !important;
    color: #579DFF !important;
}

/* Навигация и боковая панель */
#sidebar, .aui-sidebar {
    background-color: #22272B !important;
    border-right: 1px solid #454F59 !important;
}

.aui-nav-heading,
.aui-sidebar .aui-nav-heading {
    color: #738496 !important;
    border-bottom: 1px solid #454F59 !important;
}

.aui-nav > li > a,
.aui-sidebar .aui-nav > li > a {
    color: #9FADBC !important;
}

.aui-nav > li > a:hover,
.aui-sidebar .aui-nav > li > a:hover {
    background-color: #313840 !important;
    color: #579DFF !important;
}

.aui-nav .aui-nav-selected > a {
    background-color: #1C2B41 !important;
    color: #579DFF !important;
}

/* Основной контент */
#content, .aui-page-panel-content {
    background-color: #1D2125 !important;
    color: #B6C2CF !important;
}

/* Панели и модули */
.aui-page-panel,
.module,
.aui-group {
    background-color: #282E33 !important;
    border: 1px solid #454F59 !important;
    color: #B6C2CF !important;
}

.mod-header h2,
.mod-header h3,
.module .mod-header h2,
.module .mod-header h3 {
    color: #B6C2CF !important;
    background-color: #2C333A !important;
    border-bottom: 1px solid #454F59 !important;
}

/* Таблицы */
.aui-table,
.aui table,
table {
    background-color: #282E33 !important;
    border: 1px solid #454F59 !important;
}

.aui-table th,
.aui table th,
table th {
    background-color: #2C333A !important;
    color: #B6C2CF !important;
    border-bottom: 1px solid #454F59 !important;
}

.aui-table td,
.aui table td,
table td {
    background-color: #282E33 !important;
    color: #B6C2CF !important;
    border-bottom: 1px solid #454F59 !important;
}

.aui-table tbody tr:hover,
.aui table tbody tr:hover,
table tbody tr:hover {
    background-color: #313840 !important;
}

/* Issue Navigator */
.navigator-content,
.issue-container {
    background-color: #1D2125 !important;
}

.navigator-sidebar {
    background-color: #22272B !important;
    border-right: 1px solid #454F59 !important;
}

.issue-table .issuerow {
    background-color: #282E33 !important;
    border-bottom: 1px solid #454F59 !important;
}

.issue-table .issuerow:hover {
    background-color: #313840 !important;
}

.issue-table .issuerow.rowFocused {
    background-color: #1C2B41 !important;
}

/* Issue View */
.issue-header,
.issue-body {
    background-color: #282E33 !important;
    color: #B6C2CF !important;
}

.issue-header-content {
    border-bottom: 1px solid #454F59 !important;
}

/* Формы и инпуты */
.aui-form input,
.aui-form textarea,
.aui-form select,
input[type="text"],
input[type="email"],
input[type="password"],
textarea,
select {
    background-color: #2C333A !important;
    border: 1px solid #454F59 !important;
    color: #B6C2CF !important;
}

.aui-form input:focus,
.aui-form textarea:focus,
.aui-form select:focus,
input:focus,
textarea:focus,
select:focus {
    border-color: #579DFF !important;
    box-shadow: 0 0 0 2px rgba(87, 157, 255, 0.2) !important;
}

/* Кнопки */
.aui-button,
.aui-button.aui-button-primary,
button {
    background-color: #2C333A !important;
    border: 1px solid #454F59 !important;
    color: #B6C2CF !important;
}

.aui-button:hover,
button:hover {
    background-color: #313840 !important;
}

.aui-button-primary,
.aui-button.aui-button-primary {
    background-color: #579DFF !important;
    border-color: #579DFF !important;
    color: #ffffff !important;
}

.aui-button-primary:hover,
.aui-button.aui-button-primary:hover {
    background-color: #4A90E2 !important;
}

/* Дропдауны и меню */
.aui-dropdown2,
.aui-list,
.dropdown-menu {
    background-color: #282E33 !important;
    border: 1px solid #454F59 !important;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4) !important;
}

.aui-dropdown2 li > a,
.aui-list li > a,
.dropdown-menu li > a {
    color: #B6C2CF !important;
}

.aui-dropdown2 li > a:hover,
.aui-list li > a:hover,
.dropdown-menu li > a:hover {
    background-color: #313840 !important;
    color: #579DFF !important;
}

/* Комментарии */
.comment,
.activity-comment {
    background-color: #282E33 !important;
    border: 1px solid #454F59 !important;
}

.comment .comment-header,
.activity-comment .comment-header {
    background-color: #2C333A !important;
    border-bottom: 1px solid #454F59 !important;
}

/* Статусы */
.aui-lozenge {
    border: 1px solid #454F59 !important;
}

.aui-lozenge.aui-lozenge-success {
    background-color: #4BCE97 !important;
    color: #000000 !important;
}

.aui-lozenge.aui-lozenge-current {
    background-color: #F5CD47 !important;
    color: #000000 !important;
}

.aui-lozenge.aui-lozenge-error {
    background-color: #F87462 !important;
    color: #ffffff !important;
}

/* Приоритеты */
.priority-icon {
    filter: brightness(0.8);
}

/* Модальные окна */
.aui-dialog2,
.aui-blanket {
    background-color: rgba(0, 0, 0, 0.8) !important;
}

.aui-dialog2-content {
    background-color: #282E33 !important;
    color: #B6C2CF !important;
}

.aui-dialog2-header {
    background-color: #2C333A !important;
    border-bottom: 1px solid #454F59 !important;
}

/* Футер */
#footer {
    background-color: #22272B !important;
    border-top: 1px solid #454F59 !important;
    color: #738496 !important;
}

/* Хлебные крошки */
.aui-nav-breadcrumbs li a,
.breadcrumbs a {
    color: #9FADBC !important;
}

.aui-nav-breadcrumbs li a:hover,
.breadcrumbs a:hover {
    color: #579DFF !important;
}

/* Вкладки */
.aui-tabs .tabs-menu {
    border-bottom: 1px solid #454F59 !important;
}

.aui-tabs .tabs-menu .menu-item a {
    color: #9FADBC !important;
    border-bottom: 2px solid transparent !important;
}

.aui-tabs .tabs-menu .menu-item.active-tab a,
.aui-tabs .tabs-menu .menu-item a:hover {
    color: #579DFF !important;
    border-bottom-color: #579DFF !important;
}

/* Код и моноширинный текст */
code, pre, .code {
    background-color: #2C333A !important;
    color: #B6C2CF !important;
    border: 1px solid #454F59 !important;
}

/* Ссылки */
a {
    color: #579DFF !important;
}

a:hover {
    color: #4A90E2 !important;
}

/* Прогресс бары */
.aui-progress-indicator {
    background-color: #2C333A !important;
}

.aui-progress-indicator-value {
    background-color: #579DFF !important;
}

/* Уведомления */
.aui-message {
    border-left: 4px solid #579DFF !important;
    background-color: #282E33 !important;
    color: #B6C2CF !important;
}

.aui-message.success {
    border-left-color: #4BCE97 !important;
}

.aui-message.warning {
    border-left-color: #F5CD47 !important;
}

.aui-message.error {
    border-left-color: #F87462 !important;
}

/* Поиск */
#quickSearchInput,
.aui-field-search input {
    background-color: #2C333A !important;
    border: 1px solid #454F59 !important;
    color: #B6C2CF !important;
}

/* Дополнительные селекторы для лучшей совместимости */
.jira-issue-header {
    background-color: #282E33 !important;
    color: #B6C2CF !important;
}

.issue-data-block {
    background-color: #282E33 !important;
    border: 1px solid #454F59 !important;
}

.toolbar {
    background-color: #22272B !important;
    border-bottom: 1px solid #454F59 !important;
}

.toolbar .toolbar-item {
    color: #B6C2CF !important;
}

.toolbar .toolbar-item:hover {
    background-color: #313840 !important;
    color: #579DFF !important;
}

/* Фильтры */
.navigator-filter {
    background-color: #282E33 !important;
    border: 1px solid #454F59 !important;
}

/* Панель действий */
.aui-toolbar {
    background-color: #22272B !important;
    border-bottom: 1px solid #454F59 !important;
}

.aui-toolbar .toolbar-item {
    color: #B6C2CF !important;
}

.aui-toolbar .toolbar-item:hover {
    background-color: #313840 !important;
}

/* Активности и логи */
.activity-stream-item {
    background-color: #282E33 !important;
    border-bottom: 1px solid #454F59 !important;
    color: #B6C2CF !important;
}

/* Пагинация */
.aui-page .pagination {
    background-color: #282E33 !important;
}

.aui-page .pagination a {
    color: #579DFF !important;
    background-color: #2C333A !important;
    border: 1px solid #454F59 !important;
}

.aui-page .pagination a:hover {
    background-color: #313840 !important;
}
